// Minimal re-implementation of the CPython `repr()` rules that this project
// needs: string literals and list literals. Keeping it here means the whoosh
// layer never has to think about quoting.

const SIMPLE_ESCAPES = new Map([
  ['\\', '\\\\'],
  ['\n', '\\n'],
  ['\r', '\\r'],
  ['\t', '\\t'],
]);

function escapeCodePoint(cp) {
  if (cp <= 0xff) return '\\x' + cp.toString(16).padStart(2, '0');
  if (cp <= 0xffff) return '\\u' + cp.toString(16).padStart(4, '0');
  return '\\U' + cp.toString(16).padStart(8, '0');
}

// CPython only escapes characters that are not printable; everything in the
// Latin-1 control ranges plus the surrogate/BOM oddities get \x or \u form.
function isPrintable(cp) {
  if (cp < 0x20 || cp === 0x7f) return false;
  if (cp >= 0x80 && cp <= 0xa0) return false;
  if (cp === 0xad) return false;
  return true;
}

export function reprString(value) {
  const str = String(value);
  // Python prefers ' quotes, switching to " only when that avoids escaping.
  const quote = str.includes("'") && !str.includes('"') ? '"' : "'";

  let out = quote;
  for (const ch of str) {
    const cp = ch.codePointAt(0);
    const simple = SIMPLE_ESCAPES.get(ch);
    if (simple !== undefined) out += simple;
    else if (ch === quote) out += '\\' + ch;
    else if (!isPrintable(cp)) out += escapeCodePoint(cp);
    else out += ch;
  }
  return out + quote;
}

export function reprList(items, reprItem = reprString) {
  return '[' + items.map(reprItem).join(', ') + ']';
}

// Python's sorted() on str compares by Unicode code point. JS's default sort
// compares UTF-16 code units, which diverges above the BMP, so be explicit.
export function sortedStrings(values) {
  return [...values].sort((a, b) => {
    const left = [...a];
    const right = [...b];
    const shared = Math.min(left.length, right.length);
    for (let i = 0; i < shared; i += 1) {
      const d = left[i].codePointAt(0) - right[i].codePointAt(0);
      if (d !== 0) return d;
    }
    return left.length - right.length;
  });
}

