// Text helpers mirroring the pieces of Python's `textwrap` that argparse's
// HelpFormatter relies on.

// textwrap.wrap(text, width) with argparse's default options: collapse runs of
// whitespace, break on whitespace only, never break long words apart.
export function wrap(text, width) {
  const words = String(text).split(/\s+/).filter((w) => w.length > 0);
  if (words.length === 0) return [];

  const lines = [];
  let current = '';
  for (const word of words) {
    if (current === '') {
      current = word;
    } else if (current.length + 1 + word.length <= width) {
      current += ' ' + word;
    } else {
      lines.push(current);
      current = word;
    }
  }
  if (current !== '') lines.push(current);
  return lines;
}

export function repeat(char, count) {
  return count > 0 ? char.repeat(count) : '';
}

// '%*s%-*s  ' style padding used by the help formatter.
export function padRight(text, width) {
  return text.length >= width ? text : text + ' '.repeat(width - text.length);
}

