// Error/exit signalling used by the argument parser.

export class SystemExit extends Error {
  constructor(code) {
    super(`SystemExit: ${code}`);
    this.name = 'SystemExit';
    this.code = code;
  }
}

// Raised while matching arguments; the parser catches these and turns them
// into "prog: error: argument --x: <message>" on stderr.
export class ArgumentError extends Error {
  constructor(argument, message) {
    const name = getActionName(argument);
    super(name === null ? message : `argument ${name}: ${message}`);
    this.name = 'ArgumentError';
    this.argumentName = name;
  }
}

export class ArgumentTypeError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ArgumentTypeError';
  }
}

// argparse._get_action_name
export function getActionName(action) {
  if (!action) return null;
  if (action.optionStrings && action.optionStrings.length > 0) {
    return action.optionStrings.join('/');
  }
  if (action.metavar !== undefined && action.metavar !== null) return action.metavar;
  if (action.dest !== undefined && action.dest !== null) return action.dest;
  return null;
}

