// Action objects: they describe how one flag consumes argv and what it writes
// into the resulting namespace.

export const OPTIONAL = '?';
export const ZERO_OR_MORE = '*';
export const ONE_OR_MORE = '+';
export const REMAINDER = '...';
export const PARSER = 'A...';
export const SUPPRESS = '==SUPPRESS==';

export class Action {
  constructor({
    optionStrings = [],
    dest = null,
    nargs = null,
    constValue = null,
    defaultValue = null,
    type = null,
    choices = null,
    required = false,
    help = null,
    metavar = null,
  } = {}) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.nargs = nargs;
    this.constValue = constValue;
    this.defaultValue = defaultValue;
    this.type = type;
    this.choices = choices;
    this.required = required;
    this.help = help;
    this.metavar = metavar;
  }

  // eslint-disable-next-line no-unused-vars
  call(parser, namespace, values, optionString = null) {
    throw new Error('.call() not implemented');
  }
}

export class StoreAction extends Action {
  call(parser, namespace, values) {
    namespace[this.dest] = values;
  }
}

export class StoreTrueAction extends Action {
  constructor(options) {
    super({ ...options, nargs: 0, constValue: true, defaultValue: false });
  }

  call(parser, namespace) {
    namespace[this.dest] = true;
  }
}

export class HelpAction extends Action {
  constructor(options) {
    super({ ...options, nargs: 0, defaultValue: SUPPRESS });
  }

  call(parser) {
    parser.printHelp();
    parser.exit(0);
  }
}

