    const consumePositionals = (startIndex) => {
      const selectedPattern = argStringsPattern.slice(startIndex);
      const argCounts = this.matchArgumentsPartial(positionals, selectedPattern);
      let index = startIndex;
      for (let i = 0; i < argCounts.length; i += 1) {
        const action = positionals[i];
        const count = argCounts[i];
        takeAction(action, argStrings.slice(index, index + count));
        index += count;
      }
      positionals.splice(0, argCounts.length);
      return index;
    };

    const optionIndices = [...optionTuples.keys()].sort((a, b) => a - b);
    const maxOptionStringIndex = optionIndices.length > 0
      ? optionIndices[optionIndices.length - 1]
      : -1;

    let startIndex = 0;
    while (startIndex <= maxOptionStringIndex) {
      const nextOptionStringIndex = optionIndices.find((idx) => idx >= startIndex);

      if (startIndex !== nextOptionStringIndex) {
        const positionalsEndIndex = consumePositionals(startIndex);
        if (positionalsEndIndex > startIndex) {
          startIndex = positionalsEndIndex;
          continue;
        }
        startIndex = positionalsEndIndex;
      }

      if (startIndex !== nextOptionStringIndex) {
        extras.push(...argStrings.slice(startIndex, nextOptionStringIndex));
        startIndex = nextOptionStringIndex;
      }

      startIndex = consumeOptional(nextOptionStringIndex);
    }

    const stopIndex = consumePositionals(startIndex);
    extras.push(...argStrings.slice(stopIndex));

    const requiredActions = [];
    for (const action of this.actions) {
      if (seenActions.has(action)) continue;
      if (action.required) requiredActions.push(getActionName(action));
    }
    if (requiredActions.length > 0) {
      this.error(`the following arguments are required: ${requiredActions.join(', ')}`);
    }

    return [namespace, extras];
  }

  // ---- classification ----------------------------------------------------

  // argparse._parse_optional: null means "treat as a positional".
  parseOptional(argString) {
    if (argString.length === 0) return null;
    if (!this.prefixChars.includes(argString[0])) return null;

    if (this.optionStringActions.has(argString)) {
      return [this.optionStringActions.get(argString), argString, null];
    }
    if (argString.length === 1) return null;

    const eq = argString.indexOf('=');
    if (eq >= 0) {
      const optionString = argString.slice(0, eq);
      const explicitArg = argString.slice(eq + 1);
      if (this.optionStringActions.has(optionString)) {
        return [this.optionStringActions.get(optionString), optionString, explicitArg];
      }
    }

    const tuples = this.getOptionTuples(argString);
    if (tuples.length > 1) {
      const options = tuples.map(([, optionString]) => optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${options}`);
    } else if (tuples.length === 1) {
      return tuples[0];
    }

    if (NEGATIVE_NUMBER.test(argString) && !this.hasNegativeNumberOptionals) return null;
    if (argString.includes(' ')) return null;

    return [null, argString, null];
  }

  // argparse._get_option_tuples: prefix matching for abbreviated options.
  getOptionTuples(optionString) {
    const result = [];
    const chars = this.prefixChars;

    if (chars.includes(optionString[0]) && chars.includes(optionString[1])) {
      if (!this.allowAbbrev) return result;
      const eq = optionString.indexOf('=');
      const prefix = eq >= 0 ? optionString.slice(0, eq) : optionString;
      const explicitArg = eq >= 0 ? optionString.slice(eq + 1) : null;
      for (const [candidate, action] of this.optionStringActions) {
        if (candidate.startsWith(prefix)) result.push([action, candidate, explicitArg]);
      }
      return result;
    }

    if (chars.includes(optionString[0]) && !chars.includes(optionString[1])) {
      const shortOption = optionString.slice(0, 2);
      const shortExplicitArg = optionString.slice(2);
      for (const [candidate, action] of this.optionStringActions) {
        if (candidate === shortOption) {
          result.push([action, candidate, shortExplicitArg.length > 0 ? shortExplicitArg : null]);
        } else if (candidate.startsWith(optionString)) {
          result.push([action, candidate, null]);
        }
      }
      return result;
    }

    throw new Error(`unexpected option string: ${optionString}`);
  }

  matchArgument(action, argStringsPattern) {
    const nargsPattern = this.getNargsPattern(action);
    const match = new RegExp(`^${nargsPattern}`).exec(argStringsPattern);
    if (match === null) {
      let msg = NARGS_ERRORS.get(action.nargs ?? null);
      if (msg === undefined) {
        const n = action.nargs;
        msg = `expected ${n} argument${n === 1 ? '' : 's'}`;
      }
      throw new ArgumentError(action, msg);
    }
    return match[1].length;
  }

  matchArgumentsPartial(actions, argStringsPattern) {
    const result = [];
    for (let i = actions.length; i > 0; i -= 1) {
      const pattern = actions
        .slice(0, i)
        .map((action) => this.getNargsPattern(action))
        .join('');
      const match = new RegExp(`^${pattern}`).exec(argStringsPattern);
      if (match !== null) {
        for (let g = 1; g < match.length; g += 1) result.push(match[g].length);
        break;
      }
    }
    return result;
  }

  getNargsPattern(action) {
    const nargs = action.nargs ?? null;
    let pattern;
    if (nargs === null) pattern = '(-*A-*)';
    else if (nargs === OPTIONAL) pattern = '(-*A?-*)';
    else if (nargs === ZERO_OR_MORE) pattern = '(-*[A-]*)';
    else if (nargs === ONE_OR_MORE) pattern = '(-*A[A-]*)';
    else if (nargs === REMAINDER) pattern = '([-AO]*)';
    else if (nargs === PARSER) pattern = '(-*A[-AO]*)';
    else pattern = `((?:-*A){${nargs}}-*)`;

    // A `--` may never be swallowed by an optional's own arguments.
    if (action.optionStrings.length > 0) {
      pattern = pattern.split('-*').join('').split('-').join('');
    }
    return pattern;
  }

  getValues(action, argStrings) {
    const nargs = action.nargs ?? null;
    let strings = argStrings;

    if (nargs !== PARSER && nargs !== REMAINDER) {
      const idx = strings.indexOf('--');
      if (idx >= 0) strings = [...strings.slice(0, idx), ...strings.slice(idx + 1)];
    }

    if (nargs === null) {
      const [arg] = strings;
      const value = this.getValue(action, arg);
      this.checkValue(action, value);
      return value;
    }
    if (nargs === OPTIONAL && strings.length === 0) {
      return action.constValue ?? action.defaultValue;
    }
    const values = strings.map((v) => this.getValue(action, v));
    for (const value of values) this.checkValue(action, value);
    return values;
  }

  getValue(action, argString) {
    if (!action.type) return argString;
    try {
      return action.type(argString);
    } catch (err) {
      throw new ArgumentError(action, `invalid value: ${quote(argString)}`);
    }
  }

  checkValue(action, value) {
    if (action.choices && !action.choices.includes(value)) {
      const choices = action.choices.map((c) => quote(String(c))).join(', ');
      throw new ArgumentError(
        action,
        `invalid choice: ${quote(String(value))} (choose from ${choices})`,
      );
    }
  }

  // ---- help / errors -----------------------------------------------------

  formatter() {
    return new HelpFormatter(this.prog, terminalWidth() - 2);
  }

  formatUsage() {
    const formatter = this.formatter();
    return formatter.formatUsage(this.actions);
  }

  formatHelp() {
    const formatter = this.formatter();
    let help = formatter.formatUsage(this.actions);

    if (this.description) help += `${this.description}\n\n`;

    const optionals = this.actions.filter((a) => a.optionStrings.length > 0);
    const positionals = this.actions.filter((a) => a.optionStrings.length === 0);

    formatter.indent();
    formatter.measure(this.actions);
    formatter.dedent();

    if (positionals.length > 0) {
      help += 'positional arguments:\n';
      formatter.indent();
      for (const action of positionals) {
        if (action.help === SUPPRESS) continue;
        help += formatter.formatAction(action);
      }
      formatter.dedent();
      help += '\n';
    }
    if (optionals.length > 0) {
      help += 'options:\n';
      formatter.indent();
      for (const action of optionals) {
        if (action.help === SUPPRESS) continue;
        help += formatter.formatAction(action);
      }
      formatter.dedent();
      help += '\n';
    }

    if (this.epilog) help += `${this.epilog}\n\n`;

    // argparse collapses runs of blank lines and normalises the trailing one.
    help = help.replace(/\n\n\n+/g, '\n\n');
    return `${help.replace(/^\n+/, '').replace(/\n+$/, '')}\n`;
  }

  printUsage(stream = process.stdout) {
    stream.write(this.formatUsage());
  }

  printHelp(stream = process.stdout) {
    stream.write(this.formatHelp());
  }

  error(message) {
    this.printUsage(process.stderr);
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    this.exit(2);
  }

  exit(status = 0) {
    throw new SystemExit(status);
  }
}

function quote(value) {
  return `'${value}'`;
}

// argparse's default: os.path.basename(sys.argv[0]).
function defaultProg() {
  const argv0 = process.argv[1] ?? '';
  const parts = argv0.split('/');
  return parts[parts.length - 1] || argv0;
}

