// Analysis pipeline: tokenizers turn a value into tokens, filters transform the
// token stream. Analyzers are tokenizer + filter chains.

export class Token {
  constructor({
    text = '',
    positions = false,
    chars = false,
    removeStops = true,
    mode = '',
  } = {}) {
    this.text = text;
    this.positions = positions;
    this.chars = chars;
    this.removeStops = removeStops;
    this.mode = mode;
    this.stopped = false;
    this.boost = 1.0;
    this.pos = 0;
    this.startchar = 0;
    this.endchar = 0;
  }

  copy() {
    return Object.assign(new Token(), this);
  }
}

export const STOP_WORDS = new Set([
  'a', 'an', 'and', 'are', 'as', 'at', 'be', 'by', 'can', 'for', 'from', 'have',
  'if', 'in', 'is', 'it', 'may', 'not', 'of', 'on', 'or', 'tbd', 'that', 'the',
  'this', 'to', 'us', 'we', 'when', 'will', 'with', 'yet', 'you', 'your',
]);

export const DEFAULT_PATTERN = /\w+(?:\.?\w+)*/gu;

class Composable {
  // Whoosh spells chaining as `tokenizer | filter`; JS gets a method instead.
  chain(next) {
    return new CompositeAnalyzer(this, next);
  }
}

// ---- tokenizers ----------------------------------------------------------

export class Tokenizer extends Composable {}

// Emits the whole value as a single token — used by ID fields.
export class IDTokenizer extends Tokenizer {
  *call(value, options = {}) {
    const token = new Token(options);
    token.text = value;
    if (options.chars) {
      token.startchar = options.startChar ?? 0;
      token.endchar = (options.startChar ?? 0) + value.length;
    }
    yield token;
  }
}

export class RegexTokenizer extends Tokenizer {
  constructor(pattern = DEFAULT_PATTERN, gaps = false) {
    super();
    this.pattern = pattern;
    this.gaps = gaps;
  }

  *call(value, options = {}) {
    const token = new Token(options);
    const startChar = options.startChar ?? 0;
    let pos = options.startPos ?? 0;

    if (!this.gaps) {
      const re = new RegExp(this.pattern.source, 'gu');
      let match = re.exec(value);
      while (match !== null) {
        token.text = match[0];
        token.boost = 1.0;
        if (options.positions) token.pos = pos++;
        if (options.chars) {
          token.startchar = startChar + match.index;
          token.endchar = startChar + match.index + match[0].length;
        }
        yield token;
        if (match[0].length === 0) re.lastIndex += 1;
        match = re.exec(value);
      }
      return;
    }

    let prevEnd = 0;
    const re = new RegExp(this.pattern.source, 'gu');
    const bounds = [];
    let match = re.exec(value);
    while (match !== null) {
      bounds.push([match.index, match.index + match[0].length]);
      if (match[0].length === 0) re.lastIndex += 1;
      match = re.exec(value);
    }
    for (const [start, end] of [...bounds, [value.length, value.length]]) {
      const text = value.slice(prevEnd, start);
      prevEnd = end;
      if (text.length === 0) continue;
      token.text = text;
      token.boost = 1.0;
      if (options.positions) token.pos = pos++;
      if (options.chars) {
        token.startchar = startChar + start - text.length;
        token.endchar = startChar + start;
      }
      yield token;
    }
  }
}

export class SpaceSeparatedTokenizer extends RegexTokenizer {
  constructor() {
    super(/[^ \t\r\n]+/u);
  }
}

export class CommaSeparatedTokenizer extends RegexTokenizer {
  constructor() {
    super(/[^,]+/u);
  }

  *call(value, options = {}) {
    for (const token of super.call(value, options)) {
      token.text = token.text.trim();
      yield token;
    }
  }
}

// ---- filters -------------------------------------------------------------

export class Filter extends Composable {}

export class LowercaseFilter extends Filter {
  *call(tokens) {
    for (const token of tokens) {
      token.text = token.text.toLowerCase();
      yield token;
    }
  }
}

export class StopFilter extends Filter {
  constructor({ stoplist = STOP_WORDS, minsize = 2, maxsize = null, renumber = true } = {}) {
    super();
    this.stops = stoplist === null ? new Set() : new Set(stoplist);
    this.min = minsize;
    this.max = maxsize;
    this.renumber = renumber;
  }

  *call(tokens) {
    let pos = null;
    for (const token of tokens) {
      const text = token.text;
      const keep = text.length >= this.min
        && (this.max === null || text.length <= this.max)
        && !this.stops.has(text);

      if (keep) {
        if (this.renumber && token.positions) {
          pos = pos === null ? token.pos : pos + 1;
          token.pos = pos;
        }
        token.stopped = false;
        yield token;
      } else if (!token.removeStops) {
        token.stopped = true;
        yield token;
      }
    }
  }
}

// ---- analyzers -----------------------------------------------------------

export class Analyzer extends Composable {}

export class CompositeAnalyzer extends Analyzer {
  constructor(...items) {
    super();
    this.items = [];
    for (const item of items) {
      if (item instanceof CompositeAnalyzer) this.items.push(...item.items);
      else this.items.push(item);
    }
  }

  *call(value, options = {}) {
    const [first, ...rest] = this.items;
    let stream = first.call(value, options);
    for (const item of rest) stream = item.call(stream, options);
    yield* stream;
  }
}

export function IDAnalyzer() {
  return new IDTokenizer();
}

export function KeywordAnalyzer({ lowercase = false, commas = false } = {}) {
  const tokenizer = commas ? new CommaSeparatedTokenizer() : new SpaceSeparatedTokenizer();
  return lowercase ? tokenizer.chain(new LowercaseFilter()) : tokenizer;
}

export function RegexAnalyzer({ expression = DEFAULT_PATTERN, gaps = false } = {}) {
  return new RegexTokenizer(expression, gaps);
}

export function SimpleAnalyzer({ expression = DEFAULT_PATTERN, gaps = false } = {}) {
  return new RegexTokenizer(expression, gaps).chain(new LowercaseFilter());
}

export function StandardAnalyzer({
  expression = DEFAULT_PATTERN,
  stoplist = STOP_WORDS,
  minsize = 2,
  maxsize = null,
  gaps = false,
} = {}) {
  const chain = new RegexTokenizer(expression, gaps).chain(new LowercaseFilter());
  if (stoplist === null) return chain;
  return chain.chain(new StopFilter({ stoplist, minsize, maxsize }));
}

