// Posting formats: how much per-term information a field records in the index.

export class Format {
  constructor(fieldBoost = 1.0) {
    this.fieldBoost = fieldBoost;
    this.posting = false;
    this.textual = true;
  }

  get name() {
    return this.constructor.name;
  }

  // Turn a value into [text, weight, valueData] triples using the analyzer.
  wordDatas(analyzer, value, options = {}) {
    const results = [];
    for (const token of analyzer.call(value, { ...options, positions: this.posting })) {
      results.push([token.text, 1, null]);
    }
    return results;
  }

  toString() {
    return `${this.name}(boost=${this.fieldBoost})`;
  }
}

// Records only that the term occurs in the document.
export class Existence extends Format {
  constructor(fieldBoost = 1.0) {
    super(fieldBoost);
    this.posting = false;
  }
}

// Records the number of times each term occurs.
export class Frequency extends Format {
  constructor(fieldBoost = 1.0) {
    super(fieldBoost);
    this.posting = false;
  }

  wordDatas(analyzer, value, options = {}) {
    const freqs = new Map();
    for (const token of analyzer.call(value, { ...options, positions: false })) {
      freqs.set(token.text, (freqs.get(token.text) ?? 0) + 1);
    }
    return [...freqs].map(([text, freq]) => [text, freq, null]);
  }
}

