// Posting formats: how much per-term information a field records in the index.

export class Format {
  constructor(fieldBoost = 1.0) {
    this.fieldBoost = fieldBoost;
    this.posting = false;
    this.textual = true;
  }

  get name() {
    return this.constructor.name;
  }

  // Turn a value into [text, weight, valueData] triples using the analyzer.
  wordDatas(analyzer, value, options = {}) {
    const results = [];
    for (const token of analyzer.call(value, { ...options, positions: this.posting })) {
      results.push([token.text, 1, null]);
    }
    return results;
  }

  toString() {
    return `${this.name}(boost=${this.fieldBoost})`;
  }
}

