// Field types. Each describes how one field is analyzed, indexed and stored.

import { pyClass } from '../python/callable.mjs';
import { IDAnalyzer, KeywordAnalyzer, StandardAnalyzer } from './analysis.mjs';
import { Existence, Frequency, Positions, Characters } from './formats.mjs';

export class FieldConfigurationError extends Error {
  constructor(message) {
    super(message);
    this.name = 'FieldConfigurationError';
  }
}

// numtype markers standing in for Python's `int` / `float`.
export const INT = 'int';
export const FLOAT = 'float';

export class FieldTypeBase {
  constructor() {
    this.format = null;
    this.analyzer = null;
    this.vector = null;
    this.scorable = false;
    this.stored = false;
    this.unique = false;
    this.indexed = true;
    this.multitoken_query = 'default';
    this.sortable_typecode = null;
    this.column_type = null;
  }

  get typeName() {
    return this.constructor.name;
  }

  // Split a value into [text, weight, valueData] triples for the index.
  index(value, options = {}) {
    if (!this.format) {
      throw new Error(`${this.typeName} field has no format`);
    }
    return this.format.wordDatas(this.analyzer, value, options);
  }

  // Normalise a query term the same way indexing would.
  toBytes(value) {
    return String(value);
  }

  selfParsing() {
    return false;
  }

  sortableTerms(value) {
    return this.index(value).map(([text]) => text);
  }

  toString() {
    return `${this.typeName}(format=${this.format}, scorable=${this.scorable}, `
      + `stored=${this.stored}, unique=${this.unique})`;
  }
}

// Applies `sortable` the way whoosh does: truthy turns on a sort column.
function applySortable(field, sortable, typecode) {
  if (sortable) {
    field.column_type = typeof sortable === 'object' ? sortable : 'default';
    field.sortable_typecode = typecode;
  }
}

class IDField extends FieldTypeBase {
  constructor({
    stored = false,
    unique = false,
    field_boost = 1.0,
    sortable = false,
    analyzer = null,
  } = {}) {
    super();
    this.analyzer = analyzer ?? IDAnalyzer();
    this.format = new Existence(field_boost);
    this.stored = stored;
    this.unique = unique;
    applySortable(this, sortable, 's');
  }
}

class IDLISTField extends FieldTypeBase {
  constructor({
    stored = false,
    unique = false,
    expression = null,
    field_boost = 1.0,
  } = {}) {
    super();
    this.analyzer = KeywordAnalyzer({ commas: expression !== null });
    this.format = new Existence(field_boost);
    this.stored = stored;
    this.unique = unique;
  }
}

class TEXTField extends FieldTypeBase {
  constructor({
    analyzer = null,
    phrase = true,
    chars = false,
    stored = false,
    field_boost = 1.0,
    multitoken_query = 'default',
    sortable = false,
    lang = null,
    vector = null,
  } = {}) {
    super();
    this.analyzer = analyzer ?? StandardAnalyzer();
    const FormatClass = chars ? Characters : (phrase ? Positions : Frequency);
    this.format = new FormatClass(field_boost);
    this.multitoken_query = multitoken_query;
    this.scorable = true;
    this.stored = stored;
    this.vector = vector;
    this.lang = lang;
    applySortable(this, sortable, 's');
  }
}

class KEYWORDField extends FieldTypeBase {
  constructor({
    stored = false,
    lowercase = false,
    commas = false,
    vector = null,
    scorable = false,
    unique = false,
    field_boost = 1.0,
    sortable = false,
  } = {}) {
    super();
    this.analyzer = KeywordAnalyzer({ lowercase, commas });
    this.format = new Frequency(field_boost);
    this.scorable = scorable;
    this.stored = stored;
    this.unique = unique;
    this.vector = vector;
    applySortable(this, sortable, 's');
  }
}

class NUMERICField extends FieldTypeBase {
  constructor({
    numtype = INT,
    bits = 32,
    stored = false,
    unique = false,
    field_boost = 1.0,
    decimal_places = 0,
    shift_step = 4,
    signed = true,
    sortable = false,
    default: defaultValue = null,
  } = {}) {
    super();
    if (numtype === FLOAT) bits = 64;
    if (![8, 16, 32, 64].includes(bits)) {
      throw new FieldConfigurationError(`Invalid bits: ${bits}`);
    }
    if (numtype !== INT && decimal_places) {
      throw new FieldConfigurationError('decimal_places requires an integer numtype');
    }

    this.numtype = numtype;
    this.bits = bits;
    this.stored = stored;
    this.unique = unique;
    this.decimal_places = decimal_places;
    this.shift_step = shift_step;
    this.signed = signed;
    this.analyzer = IDAnalyzer();
    this.format = new Existence(field_boost);
    this.default = defaultValue;
    this.sortable_typecode = numtype === FLOAT ? 'd' : (signed ? 'q' : 'Q');
    if (sortable) this.column_type = 'default';
  }

  // Numeric fields answer range queries themselves rather than via the parser.
  selfParsing() {
    return true;
  }

  prepareNumber(value) {
    if (value === null || value === undefined) return null;
    let number = typeof value === 'number' ? value : Number(value);
    if (Number.isNaN(number)) {
      throw new FieldConfigurationError(`Could not convert ${value} to a number`);
    }
    if (this.numtype === INT) {
      if (this.decimal_places) number *= 10 ** this.decimal_places;
      number = Math.trunc(number);
    }
    return number;
  }

  // Sortable, order-preserving key: flip the sign bit so that the unsigned
  // ordering of the encoded value matches the numeric ordering.
  toBytes(value) {
    const number = this.prepareNumber(value);
    if (number === null) return '';
    const width = this.bits / 4;
    if (this.numtype === FLOAT) {
      const buf = new DataView(new ArrayBuffer(8));
      buf.setFloat64(0, number);
      let bits = buf.getBigUint64(0);
      bits = (bits & 0x8000000000000000n) !== 0n
        ? ~bits & 0xffffffffffffffffn
        : bits | 0x8000000000000000n;
      return bits.toString(16).padStart(width, '0');
    }
