  constructor(options = {}) {
    super({ ...options, numtype: INT, bits: 64 });
  }

  prepareNumber(value) {
    if (value === null || value === undefined) return null;
    if (value instanceof Date) return value.getTime() * 1000;
    return super.prepareNumber(value);
  }
}

class BOOLEANField extends FieldTypeBase {
  constructor({ stored = false, field_boost = 1.0, sortable = false } = {}) {
    super();
    this.format = new Existence(field_boost);
    this.stored = stored;
    this.bits = 8;
    applySortable(this, sortable, 'B');
  }

  toBytes(value) {
    return value ? 't' : 'f';
  }

  index(value) {
    return [[this.toBytes(value), 1, null]];
  }
}

class STOREDField extends FieldTypeBase {
  constructor() {
    super();
    this.stored = true;
    this.indexed = false;
  }

  index() {
    return [];
  }
}

// Exported under whoosh's uppercase names, callable with or without `new`.
export const FieldType = pyClass(FieldTypeBase);
export const ID = pyClass(IDField);
export const IDLIST = pyClass(IDLISTField);
export const TEXT = pyClass(TEXTField);
export const KEYWORD = pyClass(KEYWORDField);
export const NUMERIC = pyClass(NUMERICField);
export const DATETIME = pyClass(DATETIMEField);
export const BOOLEAN = pyClass(BOOLEANField);
export const STORED = pyClass(STOREDField);

