// Schema: the mapping of field names to field types.

import { reprList, sortedStrings } from '../python/repr.mjs';
import { FieldTypeBase, FieldConfigurationError } from './fieldtypes.mjs';

export class SchemaClass {
  // Python's Schema(**kwargs); insertion order is kept, but names() sorts.
  constructor(fields = {}) {
    this._fields = new Map();
    this._dyn_fields = new Map();

    for (const name of Object.keys(fields)) {
      this.add(name, fields[name]);
    }
  }

  // Sorted list of field names — this is what repr() shows.
  names() {
    return sortedStrings(this._fields.keys());
  }

  items() {
    return this.names().map((name) => [name, this._fields.get(name)]);
  }

  storedNames() {
    return this.names().filter((name) => this._fields.get(name).stored);
  }

  scorableNames() {
    return this.names().filter((name) => this._fields.get(name).scorable);
  }

  add(name, fieldtype, glob = false) {
    if (name.startsWith('_')) {
      throw new FieldConfigurationError(`Field names cannot start with an underscore: ${name}`);
    }
    if (name.includes(' ')) {
      throw new FieldConfigurationError(`Field names cannot contain spaces: ${name}`);
    }
    if (this._fields.has(name) || this._dyn_fields.has(name)) {
      throw new FieldConfigurationError(`Schema already has a field ${name}`);
    }

    // A bare field class is instantiated with its defaults, matching whoosh's
    // `if callable(fieldtype): fieldtype = fieldtype()`.
    let resolved = fieldtype;
    if (typeof resolved === 'function') {
      try {
        resolved = resolved();
      } catch (err) {
        throw new FieldConfigurationError(`Error instantiating field ${fieldtype}: ${err.message}`);
      }
    }
    if (!(resolved instanceof FieldTypeBase)) {
      throw new FieldConfigurationError(`${resolved} is not a FieldType object`);
    }

    if (glob) this._dyn_fields.set(name, resolved);
    else this._fields.set(name, resolved);
    return resolved;
  }

  remove(name) {
    if (!this._fields.has(name)) {
      throw new Error(`KeyError: ${name}`);
    }
    this._fields.delete(name);
  }

  has(name) {
    return this._fields.has(name) || this._dyn_fields.has(name);
  }

  get(name) {
    const field = this._fields.get(name) ?? this._dyn_fields.get(name);
    if (field === undefined) throw new Error(`Unknown field ${name}`);
    return field;
  }

  *[Symbol.iterator]() {
    for (const name of this.names()) yield this._fields.get(name);
  }

  get length() {
    return this._fields.size;
  }

  // "<Schema: ['id', 'price', 'tags', 'title']>"
  repr() {
    return `<${this.constructor.name.replace(/Class$/, '')}: ${reprList(this.names())}>`;
  }

  toString() {
    return this.repr();
  }
}

// Schema(...) accepts an object of fieldname -> fieldtype, mirroring kwargs.
export function Schema(fields = {}) {
  return new SchemaClass(fields);
}

