  get length() {
    return this._fields.size;
  }

  // "<Schema: ['id', 'price', 'tags', 'title']>"
  repr() {
    return `<${this.constructor.name.replace(/Class$/, '')}: ${reprList(this.names())}>`;
  }

  toString() {
    return this.repr();
  }
}

// Schema(...) accepts an object of fieldname -> fieldtype, mirroring kwargs.
export function Schema(fields = {}) {
  return new SchemaClass(fields);
}

