// Port of argparse.HelpFormatter, limited to the sections this parser emits:
// a usage line and a flat list of optionals.

import { wrap, padRight } from '../python/text.mjs';
import { OPTIONAL, ZERO_OR_MORE, ONE_OR_MORE, REMAINDER, PARSER, SUPPRESS } from './action.mjs';

const INDENT_INCREMENT = 2;
const MAX_HELP_POSITION = 24;

export class HelpFormatter {
  constructor(prog, width) {
    this.prog = prog;
    this.width = width;
    this.maxHelpPosition = Math.min(
      MAX_HELP_POSITION,
      Math.max(width - 20, INDENT_INCREMENT * 2),
    );
    this.currentIndent = 0;
    this.actionMaxLength = 0;
  }

  indent() {
    this.currentIndent += INDENT_INCREMENT;
  }

  dedent() {
    this.currentIndent -= INDENT_INCREMENT;
  }

  // Mirrors HelpFormatter.add_argument's bookkeeping of the help column.
  measure(actions) {
    for (const action of actions) {
      if (action.help === SUPPRESS) continue;
      const invocation = this.formatActionInvocation(action);
      const length = invocation.length + INDENT_INCREMENT;
      if (length > this.actionMaxLength) this.actionMaxLength = length;
    }
  }

  // ---- usage -------------------------------------------------------------

  formatUsage(actions, prefix = 'usage: ') {
    const optionals = actions.filter((a) => a.optionStrings.length > 0);
    const positionals = actions.filter((a) => a.optionStrings.length === 0);

    const optionalParts = this.formatActionsUsage(optionals);
    const positionalParts = this.formatActionsUsage(positionals);
    const actionUsage = [optionalParts.join(' '), positionalParts.join(' ')]
      .filter((s) => s.length > 0)
      .join(' ');
    let usage = [this.prog, actionUsage].filter((s) => s.length > 0).join(' ');

    const textWidth = this.width - this.currentIndent;
    if (prefix.length + usage.length > textWidth) {
      usage = this.wrapUsage(prefix, optionalParts, positionalParts, textWidth);
    }
    return `${prefix}${usage}\n\n`;
  }

  // argparse's long-usage layout: hang the option/positional groups under the
  // program name, or under the prefix when even the prog name is too wide.
  wrapUsage(prefix, optionalParts, positionalParts, textWidth) {
    const progLen = this.prog.length;
    const lines = [];

    if (prefix.length + progLen <= Math.floor(0.75 * textWidth)) {
      const indent = ' '.repeat(prefix.length + progLen + 1);
      let optLines;
      if (optionalParts.length > 0) {
        optLines = getLines(optionalParts, indent, `${prefix}${this.prog} `);
        optLines.push(...getLines(positionalParts, indent));
      } else if (positionalParts.length > 0) {
        optLines = getLines(positionalParts, `${prefix}${this.prog} `.length ? indent : indent);
        optLines[0] = `${this.prog} ${optLines[0].trimStart()}`;
      } else {
        optLines = [this.prog];
      }
      lines.push(...optLines);
      return lines.join('\n').slice(prefix.length);
    }

    const indent = ' '.repeat(prefix.length);
    const parts = [...optionalParts, ...positionalParts];
    const wrapped = getLines(parts, indent);
    if (wrapped.length > 1) {
      lines.push(this.prog, ...wrapped);
    } else {
      lines.push(`${this.prog} ${wrapped.join('')}`.trimEnd());
    }
    return lines.join('\n').slice(prefix.length);

    function getLines(chunks, lineIndent, firstPrefix = null) {
      const out = [];
      let line = [];
      let lineLen = (firstPrefix === null ? lineIndent.length : firstPrefix.length) - 1;
      for (const part of chunks) {
        if (lineLen + 1 + part.length > textWidth && line.length > 0) {
          out.push(lineIndent + line.join(' '));
          line = [];
          lineLen = lineIndent.length - 1;
        }
        lineLen += 1 + part.length;
        line.push(part);
      }
      if (line.length > 0) out.push(lineIndent + line.join(' '));
      if (firstPrefix !== null && out.length > 0) {
        out[0] = firstPrefix + out[0].slice(lineIndent.length);
      }
      return out;
    }
  }

  formatActionsUsage(actions) {
    const parts = [];
    for (const action of actions) {
      if (action.help === SUPPRESS) continue;

      if (action.optionStrings.length === 0) {
        parts.push(this.formatArgs(action, this.metavarName(action)));
        continue;
      }

      const optionString = action.optionStrings[0];
      let part;
      if (action.nargs === 0) {
        part = optionString;
      } else {
        part = `${optionString} ${this.formatArgs(action, this.metavarName(action))}`;
      }
      if (!action.required) part = `[${part}]`;
      parts.push(part);
    }
    return parts;
  }

  // ---- action entries ----------------------------------------------------

  formatAction(action) {
    const helpPosition = Math.min(this.actionMaxLength + 2, this.maxHelpPosition);
    const helpWidth = Math.max(this.width - helpPosition, 11);
    const actionWidth = helpPosition - this.currentIndent - 2;
    const header = this.formatActionInvocation(action);

    let parts;
    if (!action.help) {
      parts = [`${' '.repeat(this.currentIndent)}${header}\n`];
    } else if (header.length <= actionWidth) {
      parts = [
        `${' '.repeat(this.currentIndent)}${padRight(header, actionWidth)}  `,
      ];
      const helpLines = wrap(this.expandHelp(action), helpWidth);
      parts.push(`${helpLines[0]}\n`);
      for (const line of helpLines.slice(1)) {
        parts.push(`${' '.repeat(helpPosition)}${line}\n`);
      }
    } else {
      parts = [`${' '.repeat(this.currentIndent)}${header}\n`];
      const helpLines = wrap(this.expandHelp(action), helpWidth);
      for (const line of helpLines) {
        parts.push(`${' '.repeat(helpPosition)}${line}\n`);
      }
    }
    return parts.join('');
  }

  formatActionInvocation(action) {
    if (action.optionStrings.length === 0) {
      return this.metavarName(action);
    }
    if (action.nargs === 0) {
      return action.optionStrings.join(', ');
    }
    const args = this.formatArgs(action, this.metavarName(action));
    return action.optionStrings.map((opt) => `${opt} ${args}`).join(', ');
  }

  expandHelp(action) {
    return String(action.help);
  }

  metavarName(action) {
    if (action.metavar !== null && action.metavar !== undefined) return action.metavar;
    if (action.choices) return `{${action.choices.join(',')}}`;
    if (action.optionStrings.length > 0) return String(action.dest).toUpperCase();
    return String(action.dest);
  }

  formatArgs(action, metavar) {
    switch (action.nargs) {
      case null:
      case undefined:
        return metavar;
      case OPTIONAL:
        return `[${metavar}]`;
      case ZERO_OR_MORE:
        return `[${metavar} ...]`;
      case ONE_OR_MORE:
        return `${metavar} [${metavar} ...]`;
      case REMAINDER:
        return '...';
      case PARSER:
        return `${metavar} ...`;
      default:
        return Array.from({ length: action.nargs }, () => metavar).join(' ');
    }
  }
}

