  formatUsage(actions, prefix = 'usage: ') {
    const optionals = actions.filter((a) => a.optionStrings.length > 0);
    const positionals = actions.filter((a) => a.optionStrings.length === 0);

    const optionalParts = this.formatActionsUsage(optionals);
    const positionalParts = this.formatActionsUsage(positionals);
    const actionUsage = [optionalParts.join(' '), positionalParts.join(' ')]
      .filter((s) => s.length > 0)
      .join(' ');
    let usage = [this.prog, actionUsage].filter((s) => s.length > 0).join(' ');

    const textWidth = this.width - this.currentIndent;
    if (prefix.length + usage.length > textWidth) {
