  wrapUsage(prefix, optionalParts, positionalParts, textWidth) {
    // Greedy fill; `firstPrefix` only changes the budget of the first line,
    // whose indent is stripped again afterwards.
    const getLines = (parts, indent, firstPrefix = null) => {
      const lines = [];
      let line = [];
      let lineLen = (firstPrefix === null ? indent.length : firstPrefix.length) - 1;
