// Python's print(): str()-convert each argument, join with sep, append end.
// console.log would run objects through util.inspect instead of toString().
export function print(...values) {
  const { sep = ' ', end = '\n' } = {};
  process.stdout.write(values.map((v) => str(v)).join(sep) + end);
}

export function str(value) {
  if (value === null) return 'None';
  if (value === undefined) return 'None';
  if (value === true) return 'True';
  if (value === false) return 'False';
  return String(value);
}

