// Emits the whole value as a single token — used by ID fields.
export class IDTokenizer extends Tokenizer {
  *call(value, options = {}) {
    const token = new Token(options);
    token.text = value;
    if (options.chars) {
      token.startchar = options.startChar ?? 0;
