export class RegexTokenizer extends Tokenizer {
  constructor(pattern = DEFAULT_PATTERN, gaps = false) {
    super();
    this.pattern = pattern;
    this.gaps = gaps;
  }

  // Whoosh yields one recycled Token for speed; we yield a fresh Token per
  // match so that collecting the stream into an array behaves as expected.
  *call(value, options = {}) {
    const startChar = options.startChar ?? 0;
    let pos = options.startPos ?? 0;

    const emit = (text, start) => {
      const token = new Token(options);
      token.text = text;
      if (options.positions) token.pos = pos++;
      if (options.chars) {
        token.startchar = startChar + start;
        token.endchar = startChar + start + text.length;
      }
      return token;
    };

    const spans = matchSpans(this.pattern, value);

    if (!this.gaps) {
      for (const [start, end] of spans) {
        yield emit(value.slice(start, end), start);
      }
      return;
    }

    // In gaps mode the pattern describes the separators, so the tokens are the
    // stretches of text between (and around) the matches.
    let prevEnd = 0;
    for (const [start, end] of [...spans, [value.length, value.length]]) {
      const text = value.slice(prevEnd, start);
      const textStart = prevEnd;
      prevEnd = end;
      if (text.length === 0) continue;
      yield emit(text, textStart);
    }
  }
}

// All [start, end) spans matched by `pattern` in `value`.
function matchSpans(pattern, value) {
  const re = new RegExp(pattern.source, 'gu');
  const spans = [];
  let match = re.exec(value);
  while (match !== null) {
    spans.push([match.index, match.index + match[0].length]);
    if (match[0].length === 0) re.lastIndex += 1;
    match = re.exec(value);
  }
  return spans;
}

