// Self-tests for the library modules. These cover behaviour the entry script
// does not exercise, so the modules are verifiably functional rather than just
// enough to print one repr.

import { Schema, ID, TEXT, KEYWORD, NUMERIC, STORED, BOOLEAN, FieldConfigurationError, FLOAT }
  from '../lib/whoosh/fields.mjs';
import { StandardAnalyzer, KeywordAnalyzer, IDAnalyzer } from '../lib/whoosh/analysis.mjs';
import { reprString, reprList, sortedStrings } from '../lib/python/repr.mjs';
import { wrap } from '../lib/python/text.mjs';

let pass = 0;
let fail = 0;

function eq(desc, actual, expected) {
  const a = JSON.stringify(actual);
  const b = JSON.stringify(expected);
  if (a === b) {
    pass += 1;
  } else {
    fail += 1;
    console.log(`FAIL ${desc}\n  expected ${b}\n  actual   ${a}`);
  }
}

function raises(desc, fn) {
  try {
    fn();
    fail += 1;
    console.log(`FAIL ${desc}: expected a throw`);
  } catch {
    pass += 1;
  }
}

const tokens = (analyzer, value) => [...analyzer.call(value, { positions: true })].map((t) => t.text);

// ---- repr helpers --------------------------------------------------------
eq('repr plain', reprString('id'), "'id'");
eq('repr with quote', reprString("it's"), '"it\'s"');
eq('repr both quotes', reprString(`it's "x"`), `'it\\'s "x"'`);
eq('repr newline', reprString('a\nb'), "'a\\nb'");
eq('repr backslash', reprString('a\\b'), "'a\\\\b'");
eq('repr control', reprString('a\x01b'), "'a\\x01b'");
eq('repr list', reprList(['b', 'a']), "['b', 'a']");
eq('sorted', sortedStrings(['title', 'id', 'price', 'tags']), ['id', 'price', 'tags', 'title']);
eq('sorted case', sortedStrings(['B', 'a', 'A']), ['A', 'B', 'a']);

// ---- textwrap ------------------------------------------------------------
eq('wrap fits', wrap('show this help message and exit', 64), ['show this help message and exit']);
eq('wrap breaks', wrap('show this help message and exit', 14), ['show this help', 'message and', 'exit']);
eq('wrap empty', wrap('', 10), []);

// ---- analysis ------------------------------------------------------------
eq('standard drops stopwords', tokens(StandardAnalyzer(), 'The Quick Brown Fox'), ['quick', 'brown', 'fox']);
eq('standard lowercases', tokens(StandardAnalyzer(), 'HELLO World'), ['hello', 'world']);
eq('standard keeps dotted', tokens(StandardAnalyzer(), 'read config.ini now'), ['read', 'config.ini', 'now']);
eq('standard drops short', tokens(StandardAnalyzer(), 'a b cd'), ['cd']);
eq('id analyzer is whole value', tokens(IDAnalyzer(), 'Doc/123 x'), ['Doc/123 x']);
eq('keyword splits on space', tokens(KeywordAnalyzer(), 'Red Green  Blue'), ['Red', 'Green', 'Blue']);
eq('keyword lowercase opt', tokens(KeywordAnalyzer({ lowercase: true }), 'Red Green'), ['red', 'green']);
eq('keyword commas', tokens(KeywordAnalyzer({ commas: true }), 'red, green ,blue'), ['red', 'green', 'blue']);

// positions are renumbered after stopword removal
const positioned = [...StandardAnalyzer().call('the quick brown fox', { positions: true })]
  .map((t) => [t.text, t.pos]);
eq('positions renumbered', positioned, [['quick', 0], ['brown', 1], ['fox', 2]]);

// ---- formats via field.index() -------------------------------------------
eq('TEXT positions', TEXT().index('the cat sat on the cat'), [['cat', 2, [0, 3]], ['sat', 1, [1]], ['on', 1, [2]]]);
eq('TEXT no phrase -> freq', TEXT({ phrase: false }).index('cat cat dog'), [['cat', 2, null], ['dog', 1, null]]);
eq('KEYWORD frequency', KEYWORD().index('red blue red'), [['red', 2, null], ['blue', 1, null]]);
eq('ID existence', ID().index('abc def'), [['abc def', 1, null]]);
eq('STORED indexes nothing', STORED().index('x'), []);

// ---- numeric encoding is order-preserving --------------------------------
const price = NUMERIC();
const keys = [-2147483648, -1000, -1, 0, 1, 1000, 2147483647].map((n) => price.toBytes(n));
eq('numeric keys sort numerically', keys, [...keys].sort());
eq('numeric zero key', price.toBytes(0), '80000000');
eq('numeric decimal places', NUMERIC({ decimal_places: 2 }).toBytes(12.34), NUMERIC().toBytes(1234));
const fkeys = [-1.5, -0.5, 0, 0.5, 1.5, 1e10].map((n) => NUMERIC({ numtype: FLOAT }).toBytes(n));
eq('float keys sort numerically', fkeys, [...fkeys].sort());
eq('float forces 64 bits', NUMERIC({ numtype: FLOAT, bits: 32 }).bits, 64);
eq('boolean bytes', [BOOLEAN().toBytes(true), BOOLEAN().toBytes(false)], ['t', 'f']);
raises('bad bits rejected', () => NUMERIC({ bits: 7 }));

// ---- schema --------------------------------------------------------------
const schema = Schema({
  id: ID({ stored: true }),
  title: TEXT({ stored: true }),
  tags: KEYWORD,
  price: NUMERIC({ stored: true }),
});

eq('repr', String(schema), "<Schema: ['id', 'price', 'tags', 'title']>");
eq('names sorted', schema.names(), ['id', 'price', 'tags', 'title']);
eq('length', schema.length, 4);
eq('stored names', schema.storedNames(), ['id', 'price', 'title']);
eq('scorable names', schema.scorableNames(), ['title']);
eq('has', [schema.has('id'), schema.has('nope')], [true, false]);

// a bare class is instantiated with defaults, like whoosh's callable() check
eq('bare class instantiated', schema.get('tags').typeName, 'KEYWORDField');
eq('bare class defaults', schema.get('tags').stored, false);
eq('instance kwargs kept', schema.get('id').stored, true);
eq('field types', schema.names().map((n) => schema.get(n).typeName),
  ['IDField', 'NUMERICField', 'KEYWORDField', 'TEXTField']);
eq('iteration follows names', [...schema].map((f) => f.typeName),
  ['IDField', 'NUMERICField', 'KEYWORDField', 'TEXTField']);
eq('items', schema.items().map(([n]) => n), ['id', 'price', 'tags', 'title']);

raises('underscore name rejected', () => Schema({ _bad: ID }));
raises('duplicate name rejected', () => {
  const s = Schema({ a: ID });
  s.add('a', TEXT);
});
raises('space in name rejected', () => Schema({}).add('bad name', ID));
raises('non-field rejected', () => Schema({ x: 42 }));
try {
  Schema({ x: 42 });
} catch (err) {
  eq('non-field error type', err instanceof FieldConfigurationError, true);
}

const removable = Schema({ a: ID, b: TEXT });
removable.remove('a');
eq('remove', removable.names(), ['b']);

console.log(`${pass} passed, ${fail} failed`);
process.exit(fail === 0 ? 0 : 1);
